let realData = embeddedNasaJson.daily_data;
let selectedRecord = realData[0];
let selectedGoal = "Water Conservation";
let map, marker;
let chartInstance = null;

const goalAdviceMap = {
  "Water Conservation": {
    label: "توفير المياه وحماية التربة",
    advice: "تم ضبط التحليل للتركيز على رطوبة الجذور (GWETROOT) وتقليل فاقد التبخر في النصارية.",
    stat1: "توفير 35%", stat1Sub: "من مياه الري",
    stat2: "تحسين 30%", stat2Sub: "في خصوبة التربة"
  },
  "Yield Enhancement": {
    label: "زيادة الإنتاجية",
    advice: "تم تحسين الجدول التراكمي للأمطار (Cumulative Rainfall) لتنظيم وقت البذر للحصول على أعلى عائد محلي.",
    stat1: "زيادة 25%", stat1Sub: "في كمية المحصول",
    stat2: "تثبيت النيتروجين", stat2Sub: "بأعلى معدل طبيعي"
  },
  "Drought Resilience": {
    label: "مقاومة الجفاف",
    advice: "يتم تحليل المدى الحراري اليومي (Diurnal Temp Range) لحماية الأوراق من الإجهاد الحراري السريع.",
    stat1: "تحمل 100%", stat1Sub: "لفترات انحباس المطر",
    stat2: "حماية الجذور", stat2Sub: "من الجفاف السطحي"
  }
};

function selectGoal(goalValue) {
  selectedGoal = goalValue;
  
  document.getElementById('goal-card-water').classList.remove('goal-card-selected');
  document.getElementById('goal-card-yield').classList.remove('goal-card-selected');
  document.getElementById('goal-card-drought').classList.remove('goal-card-selected');

  if (goalValue === 'Water Conservation') {
    document.getElementById('goal-card-water').classList.add('goal-card-selected');
  } else if (goalValue === 'Yield Enhancement') {
    document.getElementById('goal-card-yield').classList.add('goal-card-selected');
  } else if (goalValue === 'Drought Resilience') {
    document.getElementById('goal-card-drought').classList.add('goal-card-selected');
  }

  const radioBtn = document.querySelector(`input[name="goal"][value="${goalValue}"]`);
  if (radioBtn) radioBtn.checked = true;
}

function populateDateOptions() {
  const dateSelect = document.getElementById('input-date');
  dateSelect.innerHTML = '';
  realData.forEach((item, index) => {
    const cleanDate = item.DATE.split(' ')[0];
    const opt = document.createElement('option');
    opt.value = index;
    opt.innerText = cleanDate;
    dateSelect.appendChild(opt);
  });
  selectedRecord = realData[0];
}

function onDateSelect(index) {
  selectedRecord = realData[index];
}

function goToStep(stepNumber) {
  try {
    const s1 = document.getElementById('screen-1');
    const s2 = document.getElementById('screen-2');
    const s3 = document.getElementById('screen-3');

    if (s1) s1.classList.add('hidden');
    if (s2) s2.classList.add('hidden');
    if (s3) s3.classList.add('hidden');

    for (let i = 1; i <= 3; i++) {
      const btn = document.getElementById(`step-btn-${i}`);
      if (btn) {
        if (i === stepNumber) {
          btn.classList.add('text-[#58EB4C]');
          btn.classList.remove('text-gray-300');
        } else {
          btn.classList.remove('text-[#58EB4C]');
          btn.classList.add('text-gray-300');
        }
      }
    }

    const targetScreen = document.getElementById(`screen-${stepNumber}`);
    if (targetScreen) {
      targetScreen.classList.remove('hidden');
    }

    if (stepNumber === 1 && map) {
      setTimeout(() => { map.invalidateSize(); }, 200);
    } else if (stepNumber === 2) {
      updateScreen2Data();
      renderChart();
    } else if (stepNumber === 3) {
      updateScreen3GoalStats();
    }

    window.scrollTo({ top: 0, behavior: 'smooth' });

  } catch (err) {
    console.error("خطأ أثناء التنقل بين الشاشات:", err);
  }
}

function handleFormSubmit(e) {
  if (e) e.preventDefault();
  goToStep(2);
}

function updateScreen2Data() {
  if (!selectedRecord) return;

  const dateStr = selectedRecord.DATE.split(' ')[0];
  const dateParts = dateStr.split('-');
  const currentMonth = parseInt(dateParts[1], 10);

  document.getElementById('display-date').innerText = dateStr;
  
  const currentGoalConfig = goalAdviceMap[selectedGoal] || goalAdviceMap["Water Conservation"];
  document.getElementById('display-goal').innerText = currentGoalConfig.label;
  document.getElementById('goal-custom-advice').innerText = currentGoalConfig.advice;

  const soilStatus = selectedRecord["Soil Moisture Status"] || "Very dry";
  const tempMax = parseFloat(selectedRecord.T2M_MAX || 35);
  const isWinterSeason = (currentMonth >= 9 && currentMonth <= 12);

  let dynamicCond = selectedRecord["ma7mod condition"] || "جاهز للزراعة";
  let reasonText = "";
  let isSuccessState = true;

  if (!isWinterSeason) {
    dynamicCond = "تنبيه موسمي: لا ينصح ببذر المحاصيل الشتوية حالياً";
    reasonText = `الشهر الحالي (شهر ${currentMonth}) خارج موسم زراعة البقوليات الشتوية (الفول والعدس)، انتظر حلول الخريف/الشتاء.`;
    isSuccessState = false;
  } else if (tempMax > 35) {
    dynamicCond = "تأجيل البذر لحماية المحصول القائم";
    reasonText = `درجة الحرارة العظمى مرتفعة جداً (${tempMax}°C)، يُفضل تأجيل البذر لمنع احتراق الشتلات وحماية المحصول القائم.`;
    isSuccessState = false;
  } else if (soilStatus === "Ideal for agriculture") {
    dynamicCond = "الظروف مثالية اليوم! ابدأ زراعة المحاصيل الأساسية أو قم بالتسميد.";
    reasonText = "رطوبة التربة والدرجات الحرارية في نطاق مثالي لإنبات الجذور وتثبيت النيتروجين الطبيعي.";
    isSuccessState = true;
  } else if (soilStatus === "Saturated") {
    dynamicCond = "التربة مشبعة بالمياه، أوقف الري فوراً لتجنب تعفن الجذور واستفد من المطر.";
    reasonText = `التربة مشبعة تماماً نتيجة الأمطار التراكمية (${selectedRecord["Cumulative Rainfall"]} ملم)، أوقف الري فوراً.`;
    isSuccessState = false;
  } else if (soilStatus === "Very dry") {
    dynamicCond = "قم بري تكميلي في الصباح الباكر لتعويض نقص الرطوبة";
    reasonText = "التربة شديدة الجفاف، ينصح بالري بالتنقيط في الصباح الباكر لحماية البذور والشتلات من الجفاف.";
    isSuccessState = true;
  }

  document.getElementById('notification-text').innerText = dynamicCond;
  document.getElementById('notification-reason').innerHTML = `💡 <strong>السبب:</strong> ${reasonText}`;
  
  const navIconBg = document.getElementById('notification-icon-bg');
  const navBadge = document.getElementById('notification-badge');

  if (!isSuccessState) {
    setState(false);
    if (navIconBg) navIconBg.className = "w-12 h-12 rounded-xl bg-amber-600 text-white flex items-center justify-center text-2xl shrink-0 shadow mt-1 sm:mt-0";
    if (navBadge) {
      navBadge.className = "px-3 py-1 rounded-full text-xs font-bold bg-amber-200 text-amber-900 whitespace-nowrap self-start sm:self-center";
      navBadge.innerText = "تنبيه زراعي";
    }
  } else {
    setState(true);
    if (navIconBg) navIconBg.className = "w-12 h-12 rounded-xl bg-emerald-600 text-white flex items-center justify-center text-2xl shrink-0 shadow mt-1 sm:mt-0";
    if (navBadge) {
      navBadge.className = "px-3 py-1 rounded-full text-xs font-bold bg-emerald-200 text-emerald-800 whitespace-nowrap self-start sm:self-center";
      navBadge.innerText = "ظروف مناسبة";
    }
  }

  document.getElementById('val-soil-status').innerText = soilStatus;
  document.getElementById('val-gwetroot').innerText = `GWETROOT: ${selectedRecord.GWETROOT}`;
  document.getElementById('val-gwettop').innerText = `رطوبة الطبقة السطحية (GWETTOP): ${selectedRecord.GWETTOP}`;

  let soilText = "الظروف مثالية اليوم! ابدأ زراعة المحاصيل الأساسية أو قم بالتسميد.";
  if (soilStatus === "Very dry") soilText = "قم بري تكميلي في الصباح الباكر لتعويض نقص الرطوبة.";
  else if (soilStatus === "Saturated") soilText = "التربة مشبعة بالمياه، أوقف الري فوراً لتجنب تعفن الجذور واستفد من المطر.";
  document.getElementById('soil-desc').innerText = soilText;

  document.getElementById('val-cum-rain').innerText = `${selectedRecord["Cumulative Rainfall"]} ملم`;
  document.getElementById('val-prectotcorr').innerText = `اليومي: ${selectedRecord.PRECTOTCORR} ملم`;
  
  document.getElementById('val-temp-avg').innerText = `المعدل: ${selectedRecord.T2M}°C`;
  document.getElementById('val-temp-range').innerText = `العظمى: ${selectedRecord.T2M_MAX}°C | الصغرى: ${selectedRecord.T2M_MIN}°C`;
  document.getElementById('val-diurnal').innerText = `المدى الحراري اليومي (Diurnal Range): ${selectedRecord["Diurnal Temperature Range"]}°C`;
}

function updateScreen3GoalStats() {
  const config = goalAdviceMap[selectedGoal] || goalAdviceMap["Water Conservation"];
  const statGreen = document.getElementById('stat-green');
  const statSub1 = document.getElementById('stat-sub-1');
  const statAmber = document.getElementById('stat-amber');
  const statSub2 = document.getElementById('stat-sub-2');

  if (statGreen) statGreen.innerText = config.stat1;
  if (statSub1) statSub1.innerText = config.stat1Sub;
  if (statAmber) statAmber.innerText = config.stat2;
  if (statSub2) statSub2.innerText = config.stat2Sub;
}

function renderChart() {
  const ctx = document.getElementById('nasaChart').getContext('2d');
  if (chartInstance) chartInstance.destroy();

  const sampleData = realData.filter((_, i) => i % 10 === 0);
  const labels = sampleData.map(d => d.DATE.split(' ')[0]);
  const rainData = sampleData.map(d => d["Cumulative Rainfall"]);
  const moistureData = sampleData.map(d => d.GWETROOT * 100);

  Chart.defaults.font.family='Cairo';
  Chart.defaults.font.weight='700';
  chartInstance = new Chart(ctx, {
    type: 'line',
    data: {
      labels: labels,
      datasets: [
        {
          label: 'الأمطار التراكمية (ملم)',
          data: rainData,
          borderColor: '#0288D1',
          backgroundColor: 'rgba(2, 136, 209, 0.15)',
          fill: true,
          tension:0.4,borderWidth:3,pointRadius:0,pointHoverRadius:6
        },
        {
          label: 'مؤشر رطوبة الجذور (%)',
          data: moistureData,
          borderColor: '#2E7D32',
          backgroundColor: 'rgba(46, 125, 50, 0.15)',
          fill: true,
          tension:0.4,borderWidth:3,pointRadius:0,pointHoverRadius:6
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation:{duration:1800,easing:'easeOutQuart'},
      plugins: { legend: { position: 'top' } },
      scales: { y: { beginAtZero: true } }
    }
  });
}

window.addEventListener('DOMContentLoaded', () => {
  populateDateOptions();

  const defaultCoords = [32.2438, 35.39];
  map = L.map('map').setView(defaultCoords, 12);

  // خرائط Esri المضمونة والسريعة
  L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', {
    maxZoom: 19,
    attribution: 'Tiles &copy; Esri'
  }).addTo(map);

  marker = L.marker(defaultCoords, {
    icon: L.divIcon({
      className: 'pin',
      html: '<i></i><b></b>',
      iconSize: [30, 30],
      iconAnchor: [15, 15]
    })
  }).addTo(map)
    .bindPopup('موقع المزرعة: النصارية / نابلس (32.2438, 35.39)')
    .openPopup();

  setTimeout(() => {
    if (map) map.invalidateSize();
  }, 400);
});

function locateUserOnMap() {
  if (navigator.geolocation) {
    navigator.geolocation.getCurrentPosition((position) => {
      const lat = position.coords.latitude;
      const lng = position.coords.longitude;
      map.setView([lat, lng], 13);
      marker.setLatLng([lat, lng]).bindPopup('تم تحديد موقعك الجغرافي').openPopup();
      toast('تم تحديد موقعك ✓');
    }, () => {
      toast("تعذر الوصول لموقعك، فعّل صلاحية الموقع", false);
    });
  }
}

const $=id=>document.getElementById(id),calm=matchMedia('(prefers-reduced-motion:reduce)').matches;
const OK=`<svg class="ok" viewBox="0 0 120 110"><ellipse cx="60" cy="98" rx="46" ry="9" fill="#6b4226"/><path class="stem" pathLength="1" d="M60 98V50" stroke="#2E7D32" stroke-width="5" stroke-linecap="round" fill="none"/><path class="lf l1" d="M60 62C40 62 30 50 28 40C46 40 58 48 60 62Z" fill="#58EB4C"/><path class="lf l2" d="M60 52C80 52 90 40 92 30C74 30 62 38 60 52Z" fill="#3fbf3a"/><path class="drops" d="M30 6q4 7 0 10q-4-3 0-10M60 0q4 7 0 10q-4-3 0-10M90 6q4 7 0 10q-4-3 0-10" fill="#0288D1"/></svg>`;
