const f=$('field');for(let i=0;i<46;i++){const e=document.createElement('i');e.className='st';e.style.cssText=`--h:${50+Math.random()*90}px;--d:${2+Math.random()*2.5}s;animation-delay:-${Math.random()*3}s`;f.append(e)}
const cv=$('fx'),cx=cv.getContext('2d'),C={leaf:'#58EB4C',seed:'#f5c542',dust:'#a0703a'};let P=[];
const rs=()=>{cv.width=innerWidth;cv.height=innerHeight};rs();addEventListener('resize',rs);
function add(x,y,t,n=1,k=1){for(let i=0;i<n;i++){const a=Math.random()*6.28,v=(2+Math.random()*5)*k;P.push({x,y,t,vx:Math.cos(a)*v,vy:Math.sin(a)*v-2,r:0,vr:(Math.random()-.5)*.2,s:6+Math.random()*8,l:1})}}
(function loop(){cx.clearRect(0,0,cv.width,cv.height);P=P.filter(p=>p.l>0);for(const p of P){p.x+=p.vx;p.y+=p.vy;p.vy+=p.t=='dust'?.01:.12;p.vx*=.985;p.r+=p.vr;p.l-=.011;cx.save();cx.globalAlpha=Math.min(p.l,1);cx.translate(p.x,p.y);cx.rotate(p.r);cx.fillStyle=C[p.t];cx.beginPath();if(p.t=='leaf'){cx.moveTo(0,-p.s);cx.quadraticCurveTo(p.s,0,0,p.s);cx.quadraticCurveTo(-p.s,0,0,-p.s)}else cx.arc(0,0,p.t=='dust'?p.s/2:p.s/3,0,7);cx.fill();cx.restore()}requestAnimationFrame(loop)})();
setInterval(()=>{if(!calm&&!document.hidden)P.push({x:Math.random()*innerWidth,y:-10,t:'leaf',vx:1,vy:1,r:0,vr:.03,s:6,l:1.2})},2200);
const burst=ok=>{if(calm)return;const y=innerHeight*.3;if(ok){add(innerWidth/2,y,'leaf',28);add(innerWidth/2,y,'seed',18)}else{[.2,.5,.8].forEach(k=>add(innerWidth*k,y,'dust',16,1.4))}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const r=b.getBoundingClientRect(),d=Math.max(r.width,r.height),s=document.createElement('span');s.className='rip';s.style.cssText=`width:${d}px;height:${d}px;left:${e.clientX-r.left-d/2}px;top:${e.clientY-r.top-d/2}px`;b.append(s);setTimeout(()=>s.remove(),700);if(!calm)add(e.clientX,e.clientY,'seed',8,.6)});
function setState(ok){const b=$('notification-banner');b.classList.remove('st-ok','st-no');void b.offsetWidth;b.classList.add(ok?'st-ok':'st-no')}
function toast(m,ok=true){let t=$('toast');if(!t){t=document.createElement('div');t.id='toast';document.body.append(t)}t.className='';void t.offsetWidth;t.className=ok?'t-ok':'t-no';t.innerHTML=`<i class="fa-solid ${ok?'fa-seedling':'fa-triangle-exclamation'}"></i> ${m}`;if(ok)burst(true);clearTimeout(t._h);t._h=setTimeout(()=>t.className='',3500)}

const activeGoToStep = goToStep;
window.goToStep = function(n){
  activeGoToStep(n);
  for (let i=1; i<=3; i++) {
    const stepBtn = $('step-btn-'+i);
    if (stepBtn) stepBtn.classList.toggle('step-on', i===n);
  }
  const s = $('screen-'+n);
  if (s) {
    s.classList.remove('enter');
    void s.offsetWidth;
    s.classList.add('enter');
  }
  if(n===2){
    const ok=!$('notification-banner').classList.contains('st-no');
    burst(ok);
    document.body.classList.remove('vig-ok','vig-no');
    void document.body.offsetWidth;
    document.body.classList.add(ok?'vig-ok':'vig-no');
  }
};

