function toggleOfoiqChat() {
  const win = document.getElementById('ofoiq-chat-window');
  win.classList.toggle('chat-open');
  if (win.classList.contains('chat-open')) {
    document.getElementById('ofoiq-chat-input').focus();
  }
}

function sendQuickQuestion(text) {
  document.getElementById('ofoiq-chat-input').value = text;
  handleOfoiqChatSubmit(new Event('submit'));
}

const GEMINI_API_KEY = "AQ.Ab8RN6K-J6zZ7v2Kz5P-VvZXFKf8oWUmp1hmKYzb7vFE6KBNiw";

async function handleOfoiqChatSubmit(e) {
  e.preventDefault();
  const input = document.getElementById('ofoiq-chat-input');
  const msg = input.value.trim();
  if (!msg) return;

  appendChatMessage(msg, 'user');
  input.value = '';

  const typingId = appendTypingIndicator();

  try {
    const reply = await fetchGeminiAIResponse(msg);
    removeTypingIndicator(typingId);
    appendChatMessage(reply, 'bot');
  } catch (error) {
    console.error("Gemini API Error:", error);
    removeTypingIndicator(typingId);
    const fallbackReply = generateOfoiqAIResponse(msg);
    appendChatMessage(fallbackReply, 'bot');
  }
}

async function fetchGeminiAIResponse(userQuery) {
  const currentRec = (typeof selectedRecord !== 'undefined' && selectedRecord) ? selectedRecord : embeddedNasaJson.daily_data[0];
  const dateStr = currentRec.DATE.split(' ')[0];
  const tempMax = currentRec.T2M_MAX;
  const tempMin = currentRec.T2M_MIN;
  const soilStatus = currentRec["Soil Moisture Status"];
  const rain = currentRec["Cumulative Rainfall"];
  const recommendation = currentRec["ma7mod condition"];

  const systemContext = `أنت "مستشار أفق الزراعي الذكي"، خبير زراعي متخصص في منطقة النصارية / نابلس (فلسطين).
إليك بيانات محطة NASA POWER الميدانية المباشرة لتاريخ اليوم المحدد (${dateStr}):
- الحرارة العظمى: ${tempMax}°C
- الحرارة الصغرى: ${tempMin}°C
- حالة رطوبة التربة: ${soilStatus}
- كمية الأمطار التراكمية: ${rain} ملم
- التوصية الزراعية المعتمدة من النظام: ${recommendation}

تعليمات الإجابة:
1. أجب بأسلوب خبير زراعي مشجع ومبسط للمزارع الفلسطيني.
2. استخدم بيانات اليوم المذكورة أعلاه لإعطاء إجابات دقيقة ومباشرة.
3. اجعل الإجابة مختصرة (لا تتجاوز 3-4 أسطر) ومريحة للقراءة على الهاتف.`;

  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${GEMINI_API_KEY}`;

  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      contents: [
        { role: 'user', parts: [{ text: systemContext + "\n\nسؤال المزارع: " + userQuery }] }
      ]
    })
  });

  if (!response.ok) {
    const errorData = await response.json();
    console.error("تفاصيل خطأ Gemini API:", errorData);
    throw new Error(`HTTP error! status: ${response.status}`);
  }

  const data = await response.json();
  const botMessage = data.candidates[0].content.parts[0].text;
  
  return botMessage.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>').replace(/\n/g, '<br>');
}

function appendChatMessage(text, sender) {
  const box = document.getElementById('ofoiq-chat-messages');
  const isUser = sender === 'user';
  const msgDiv = document.createElement('div');
  msgDiv.className = `flex items-start gap-2 ${isUser ? 'flex-row-reverse' : ''}`;
  
  msgDiv.innerHTML = `
    <div class="w-7 h-7 rounded-lg ${isUser ? 'bg-[#58EB4C] text-emerald-950 font-black' : 'bg-emerald-800 text-[#58EB4C]'} flex items-center justify-center text-xs shrink-0 mt-0.5">
      ${isUser ? '👨‍🌾' : '🤖'}
    </div>
    <div class="${isUser ? 'bg-[#58EB4C] text-emerald-950 rounded-tl-none font-bold' : 'bg-emerald-900/80 text-emerald-100 rounded-tr-none border border-emerald-700/60'} p-3 rounded-2xl max-w-[85%] shadow leading-relaxed">
      ${text}
    </div>
  `;
  box.appendChild(msgDiv);
  box.scrollTop = box.scrollHeight;
}

function appendTypingIndicator() {
  const box = document.getElementById('ofoiq-chat-messages');
  const id = 'typing-' + Date.now();
  const div = document.createElement('div');
  div.id = id;
  div.className = 'flex items-start gap-2';
  div.innerHTML = `
    <div class="w-7 h-7 rounded-lg bg-emerald-800 flex items-center justify-center text-[#58EB4C] text-xs shrink-0">🤖</div>
    <div class="bg-emerald-900/80 text-emerald-300 p-3 rounded-2xl rounded-tr-none border border-emerald-700/60 text-xs italic animate-pulse">
      جاري قراءة بيانات محطة النصارية... 🌱
    </div>
  `;
  box.appendChild(div);
  box.scrollTop = box.scrollHeight;
  return id;
}

function removeTypingIndicator(id) {
  const el = document.getElementById(id);
  if (el) el.remove();
}

function generateOfoiqAIResponse(userQuery) {
  const q = userQuery.toLowerCase().trim();
  const currentRec = (typeof selectedRecord !== 'undefined' && selectedRecord) ? selectedRecord : embeddedNasaJson.daily_data[0];
  const dateStr = currentRec.DATE.split(' ')[0];
  const dateParts = dateStr.split('-');
  const currentMonth = parseInt(dateParts[1], 10);

  const soilStatus = currentRec["Soil Moisture Status"] || "Very dry";
  const rain = parseFloat(currentRec["Cumulative Rainfall"] || 0);
  const tempMax = parseFloat(currentRec.T2M_MAX || 35);
  const isWinterSeason = (currentMonth >= 9 && currentMonth <= 12);

  let dynamicCondition = selectedRecCondition(currentRec, currentMonth);

  if (q.includes('ري') || q.includes('سقاية') || q.includes('ماء') || q.includes('سقي')) {
    if (soilStatus === "Saturated") {
      return `🛑 **توجيهات الري الاحترافية:**\nالتربة مشبعة بالمياه حالياً (تراكمي الأمطار: **${rain} ملم**). أوقف الري فوراً لتجنب تعفن الجذور واستفد من مياه المطر.`;
    } else if (soilStatus === "Very dry") {
      return `💧 **توجيهات الري الاحترافية:**\nالتربة جافة جداً مع حرارة عظمى **${tempMax}°C**. قم بري تكميلي في الصباح الباكر لتعويض نقص الرطوبة وتقليل فاقد التبخر.`;
    } else {
      return `🌱 **توجيهات الري الاحترافية:**\nرطوبة التربة ممتازة اليوم (${soilStatus}). حافظ على جدول ري معتدل ودوري.`;
    }
  }

  if (q.includes('بقوليات') || q.includes('ازرع') || q.includes('فول') || q.includes('عدس') || q.includes('زراعة')) {
    if (!isWinterSeason) {
      return `🛑 **تنبيه زراعي حاسم:**\nلا ينصح ببذر البقوليات الشتوية في فصل الصيف (شهر ${currentMonth}). يجب انتظار موسم الخريف/الشتاء لتفادي تلف المحصول.`;
    }
    if (tempMax > 35) {
      return `⚠️ **تحذير من إجهاد حراري:**\nدرجة الحرارة العظمى مرتفعة جداً (**${tempMax}°C**). التوصية العلمية هي: **"تأجيل البذر لحماية المحصول القائم والشتلات"**.`;
    }
    return `✅ **التوصية الزراعية المعتمدة (**${dateStr}**):**\n📢 **"${dynamicCondition}"**`;
  }

  if (q.includes('تربة') || q.includes('رطوبة') || q.includes('حالة')) {
    return `📊 **تقرير حالة التربة والطقس بالنصارية (**${dateStr}**):**\n• حالة التربة: **${soilStatus}**\n• الحرارة العظمى: **${tempMax}°C**\n• الأمطار التراكمية: **${rain} ملم**\n• التوصية المباشرة: **${dynamicCondition}**`;
  }

  return `أهلاً بك يا زارع الخير! بناءً على بيانات NASA POWER لمحطة النصارية بتاريخ **${dateStr}**:\n\n📢 **التوصية المباشرة:** "${dynamicCondition}"\n🌡️ **الحرارة العظمى:** ${tempMax}°C\n🌱 **حالة التربة:** ${soilStatus}`;
}

function selectedRecCondition(rec, month) {
  const tempMax = parseFloat(rec.T2M_MAX || 35);
  const soilStatus = rec["Soil Moisture Status"] || "Very dry";
  const isWinterSeason = (month >= 9 && month <= 12);

  if (!isWinterSeason) return "تنبيه موسمي: لا ينصح ببذر المحاصيل الشتوية خارج موسمها.";
  if (tempMax > 35) return "تأجيل البذر لحماية المحصول القائم";
  if (soilStatus === "Ideal for agriculture") return "الظروف مثالية اليوم! ابدأ زراعة المحاصيل الأساسية أو قم بالتسميد.";
  if (soilStatus === "Saturated") return "التربة مشبعة بالمياه، أوقف الري فوراً لتجنب تعفن الجذور واستفد من المطر.";
  if (soilStatus === "Very dry") return "قم بري تكميلي في الصباح الباكر لتعويض نقص الرطوبة";
  return rec["ma7mod condition"] || "جاهز للزراعة";
}
